import { auth } from "@/lib/auth";
import { redirect } from "next/navigation";
import { getT } from "@/lib/i18n/server";
import { prisma } from "@/lib/prisma";
import { canViewGovernance } from "@/lib/rbac";
import { PrintButton } from "../../../paperwork/print-button";
import { DocFooter, DocHeader, DocSheet } from "../../../paperwork/doc-shell";

// Printable volunteer contract following the mandatory clauses of law 06.18
// (identity of both parties, mission, weekly hours, duration, insurance).
export default async function ContractPrintPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const session = await auth();
  if (!session) redirect("/login");
  if (!canViewGovernance(session.user.roles)) redirect("/unauthorized");
  const { t } = await getT();
  const { id } = await params;

  const contract = await prisma.volunteerContract.findUnique({ where: { id } });
  if (!contract) {
    return (
      <div className="py-16 text-center">
        <a href="/bureau/volunteer-contracts" className="text-primary underline">{t("gov.paperwork.backToHub")}</a>
      </div>
    );
  }

  const associationInfo = await prisma.associationInfo.findFirst();
  const name = associationInfo?.name ?? "جمعية النعمة";

  const fmt = (d: Date | null, fallback = "—") =>
    d ? new Date(d.getTime() + 43_200_000).toLocaleDateString("ar-MA", { dateStyle: "long" }) : fallback;

  return (
    <div className="py-4">
      <PrintButton />
      <DocSheet>
        <DocHeader associationName={name} city={associationInfo?.city} />

        <h1 className="mt-8 text-center text-xl font-extrabold underline" dir="rtl">
          عقد تطوع تعاقدي
          <span className="block text-xs font-normal text-muted-foreground"> (القانون رقم 06.18 — القانون-إطار للتطوع التعاقدي)</span>
        </h1>

        <section className="mt-8 space-y-1 text-base leading-relaxed" dir="rtl">
          <p><b>الطرف الأول (الجهة المنظمة):</b> {name}{associationInfo?.address ? ` — ${associationInfo.address}` : ""}</p>
          <p>
            <b>الطرف الثاني (المتطوع المتعاقد):</b> {contract.volunteerName}
            {contract.cin ? ` — ب.ت.و: ${contract.cin}` : ""}
            {contract.birthDate ? ` — المولود(ة) في ${fmt(contract.birthDate)}` : ""}
            {contract.phone ? ` — الهاتف: ${contract.phone}` : ""}
            {contract.address ? ` — العنوان: ${contract.address}` : ""}
          </p>
        </section>

        <section className="mt-6 space-y-2 text-base leading-relaxed" dir="rtl">
          <p><b>1. موضوع التطوع:</b> {contract.missionTitle}</p>
          {contract.missionDetails && (
            <pre className="whitespace-pre-wrap rounded-lg bg-muted/60 p-3 font-sans">{contract.missionDetails}</pre>
          )}
          <p>
            <b>2. مدة العقد:</b> من {fmt(contract.startDate)}
            {contract.endDate ? ` إلى ${fmt(contract.endDate)}` : " ولغاية إنجاز المهمة"}
            {contract.weeklyHours !== null ? <>، بمعدل <b>{Number(contract.weeklyHours)}</b> ساعة في الأسبوع</> : null}.
          </p>
          <p><b>3. تأمين المتطوع:</b> يخضع المتطوع لتغطية التأمين عن الحوادث{contract.insuranceRef ? ` تحت المرجع: ${contract.insuranceRef}` : ""}.</p>
          <p><b>4. فسخ العقد:</b> يمكن لكل من الطرفين إنهاء هذا العقد بإشعار كتابي مسبق، دون تعويض، مع احترام كرامة المتطوع وعدم استغلال نشاطه لأغراض تجارية أو دعائية أو انتخابية.</p>
          {contract.notes && <p><b>5. شروط خاصة:</b> {contract.notes}</p>}
        </section>

        <p className="mt-8 text-sm text-muted-foreground" dir="rtl">
          حُرر بمقر الجمعية في {fmt(new Date(), "..........")} في نسختين، تسلم كل طرف نسخة.
        </p>

        <DocFooter left={t("gov.paperwork.signaturePresident")} right={`توقيع المتطوع: ${contract.volunteerName}`} />
      </DocSheet>
    </div>
  );
}
